exec((__import__('pathlib').Path(__file__).parent/'ghost_a.py').read_text(encoding='utf-8').split("B('不祥之兆'")[0])
B('鬼胎之一',[
C('a_bi','阿碧','阿碧在贫穷的八子女家庭中长大，很早离开学校，先做家庭手工业，后进工厂，到十八岁已是熟练车衣工。她容貌娟秀，却一直把工作和照料弟妹放在前面。富有的丁老太太替有认知障碍的成年儿子择妻，提出足以改变全家生活的条件，阿碧在家人近乎哀求的目光中答应。老太太没有隐瞒儿子状况，却公开把婚姻视为取得后代的工具，要求她接受身体检查和严密监视，甚至控制夫妻最私密的生活。阿碧觉得受辱，却为家人继续忍受，后来逐渐把丈夫当作需要照顾的大孩子。难产时，文本把她置于救母或救子的生死选择中，她恳求自己还年轻、可以再生，老太太却只要孩子。阿碧在绝望中留下死也不会放过对方的怒言，随后死亡；数月后婴儿据唯一目击者说出相似话并刺死祖母，婴儿又很快死去。复仇是否由她附身没有独立确认，原文还存在缺页。终局卡保留她被牺牲后的愤怒与生前的照料能力，不把传闻扩张成能任意占据婴儿、借任何身体复活的权能；她首先会争取被当成有意愿、有未来的人。','难产时死亡；婴儿疑似复仇属于未能证实的后续关联。','年轻娟秀的工厂女工，曾被称工厂之花；受辱时含泪而少言。','保护自身生命与尊严，也不愿家人再次陷入贫困。','长期忍耐后，在生死被他人决定时激烈求生和反抗。','熟练车衣、家务与照料经验；未证实可主动附身。',[(7,39,'贫困背景、婚姻条件与监视'),(41,59,'求生、死亡与疑似复仇')],[('家人利益要求她牺牲','自己仍有选择但压力巨大','会犹豫、衡量，并可能为家人退让。'),('身体和人生被当成工具','对方拒绝承认她的意愿','明确表达羞辱和反抗，不只顺从。'),('自身生命被别人替代决定','仍能发声求助','争取存活，要求把自己当人对待。')],revive=True,uncertainties=['55行标记缺一页，婴儿行为前的完整转折缺失。','没有确证阿碧的灵魂即婴儿行动者。']),
C('ding_matriarch','丁老太太','丁老太太不到六十岁便掌握家族庞大事业，家人都依她的意志生活。她的权力来自丈夫当年为纳妾让出的多数股份，也来自本人固执、自信和强烈控制欲。唯一儿子自幼有严重认知障碍，夫妻把他送到瑞士并向亲友隐瞒，她仍盼望通过婚姻取得一个健康孙辈。选中贫家女阿碧后，她以金钱使对方全家受益，也坦白儿子的情况；但所谓坦白没有带来平等，她要求检查、监视，并直接干预夫妻隐私。阿碧怀孕后，她照顾周到，目的却始终围绕后代延续。生产陷入危险，面对媳妇求生，她以简短而不可动摇的决定保孩子，事后用钱减轻娘家的哀伤。她对新生孙子的亲自照料与织毛衣并非虚假，恰显示她能深情，却把深情严格限定在自己认可的继承对象上。最终她被钢针刺穿心脏，儿子称是婴儿说出阿碧的怒言后动手，旁人将其当作意外。终局的她已死，不能继续自动调用整个家业；回溯参战应保留资源依赖与命令习惯，强势不等于心灵控制，财富也不能保证别人永久顺从。','被钢针刺中心脏死亡，官方式解释为意外；唯一目击叙述难获信任。','不足六十岁的家族女掌权者，关键决定时面部坚硬、紧抿嘴。','延续家族血脉和自己掌握的事业秩序。','面对反对时简短决断，把照料与控制同时施加。','财务控制、家庭权威和有条件馈赠；需真实家产与依赖关系。',[(5,33,'权力来源与安排婚姻'),(43,59,'舍弃媳妇、照料孙儿与死亡')],[('家族目标受到阻碍','认为资源能解决','用条件与承诺重排他人的生活。'),('受助者要求自主','与继承计划冲突','以结果为先，暴露冷酷取舍。'),('晚辈符合她的期待','自己认为延续获得保证','会亲自照料，展现真实但狭窄的温情。')],roles=['反派'],revive=True,uncertainties=['原文缺页且婴儿袭击主要依靠儿子目击陈述。'])],excluded=[{'name':'丁少爷','reason':'一次性被安排婚姻者及目击者，认知障碍不构成反派；未作为独立主角展开。'},{'name':'丁家男婴','reason':'疑似阿碧复仇载体但主体未知；按未明事件记录，避免虚构独立意志与可控技能。'}],notes=['正文55行有“缺一页”，附身解释不作确定能力。'])
B('鬼胎之二',[
C('dami','妲咪','妲咪与汤尼从大学新生聚会相识，经过恋爱、订婚、工作和婚姻，建立了平静而自足的两人生活。她和丈夫曾共同决定暂不生育，即使长辈催促也只微笑应对；看到汤尼在公园认真逗弄婴儿后，她主动改变计划，先不告诉丈夫，等怀孕确认才把喜讯作为惊喜。此后的准备充满家庭乐趣，但她并没有把每件事都交由汤尼决定，想知道胎儿情况时也会自己安排检查。一次夜间出现异常剧烈的腹部动作，她起初不愿惊动丈夫，最后承受不住恐惧才求助；天亮缓和后，又用普通怀孕经验安慰双方。到医院时，她发现腹部像有独立力量，把自己强行拖离扫描室。她将此理解为里面的东西不愿被提前看清，紧抓把手抵抗，并要求丈夫相信眼前的真实扭曲。最终她用导致自己死亡的方式阻止生产，腹部流血后迅速平下，原文未给胎中存在的医学解释。终局的她不是猎鬼斗士，而是从期待生命转到拼命夺回身体决定权的人；若恢复人身，不携带胎中异常作武器，也不把一次惨烈抉择设成所有困境的固定答案。','为阻止腹中未知存在出生而死亡，胎体性质未揭。','起初身形苗条，孕期有期待神情；危急时披头散发、冷汗与惊恐。','维护与丈夫的生活和自身身体的自主，拒绝让未知强行决定结果。','先自我安慰，事实清楚后会顽强抵抗。','普通人的判断、求援与身体抵抗；腹中力量不属于她的可用技能。',[(5,27,'关系、计划和主动改变'),(55,85,'异常胎动、反抗及死亡')],[('亲密关系的愿望发生变化','她认同新的生活目标','主动作决定，并寻找合适时机告知。'),('身体出现不明异常','常规解释已不能覆盖','寻专业检查并要求别人相信具体症状。'),('外来意志强迫她行动','自己仍有可选择的空间','争取控制和援助，避免把原结局机械重复。')],revive=True,uncertainties=['胎中事物究竟为何没有答案。']),
C('tony','汤尼（鬼胎之二）','汤尼与妲咪的关系从大学相识起按部就班，却并不因此缺少感情。他们在合适工作和收入支持下维持安稳小家，原先同意暂不要孩子，后来被公园里一个婴儿打动，开始委婉表达想做父亲的愿望。知道妻子怀孕后，他兴奋地购买大量婴儿用品，每次检查都陪同，还真的报名育婴课程，成为班里唯一的男人；这些行动表明他愿意为期待中的角色学习，而不只享受名义。他担心检查影响胎儿，也在异常胎动时慌忙想联系医生，专业知识虽增长，却不等于真正能诊断一切。医院来电后他冲去，看到妻子被腹中力量扭曲拖拽，最初仍无法接受她说里面不是正常孩子。等情况发展，他与护士尝试拉住妻子，却没有成功，最终只能跪在将死的她身边，感受腹部迅速变平。此后他不断追问发生了什么，却无人能答。终局的汤尼带着爱、准备落空和未解悲痛，不能把育婴知识升级成医师资格，更不能把无法救下妻子反推成懦弱。他会认真陪伴、主动学习，但面对新的未知仍需要专业协助。','妻子与预期孩子均未能存活，长期追问事件原因。','年轻上班族，照料时热切，灾变时惊恐失措。','保护亲近的人，并理解家庭期待何以崩溃。','迅速求医和赶赴现场；解释过于骇人时会短暂否认。','育婴课程与照料知识、普通求助应变；并非产科医生。',[(15,47,'想做父亲与学习照料'),(55,85,'求医、现场救援与丧失')],[('亲近者需要长期照顾','自己尚缺知识','主动上课和准备实际用品。'),('异常症状持续','超出学过的内容','联系专业人员，不只靠自信处理。'),('遭遇无法接受的真相','仍有正在受苦的人','即使语言否认，身体仍尝试靠近援助。')]),
C('dami_fetus','妲咪腹中的未知存在','它没有被直接看清，最早以被期待的胎儿身份存在于妲咪和汤尼的家庭计划中。两人购买用品、接受检查、讨论出生后的生活，并没有预先把它当作威胁。异常始于一夜强烈的腹中动作，母体感到几乎要被撑裂，天亮又平静，因而一度被解释为普通胎动。真正足以辨识独立对抗的表现出现在扫描室外：妲咪想进去，腹部却向外扭曲，力量大到能拖动她的身体，必须紧抓门边才能暂时坚持。她认为里面的东西怕被扫描暴露，想先出生成为既成事实；这一动机是她基于现象的判断，不是对方说出的计划。随后身体被拖离，丈夫与护士没能拉住，妲咪用致命方式中断局面，流血后腹部迅速变平，未发现可供说明的胎体。终局卡因此只保存一个受母体空间限制、会抵抗特定检查的未知威胁，不给予姓名、种族或邪神血统。其力量可影响所在身体的运动，却无证据能离体追猎、寄生任意人或免疫扫描；害怕被检查也不等于检查本身必然杀死它。','妲咪死亡后腹部变平，未知存在没有独立现身；是否被消灭未能确认。','未直接显形，只表现为隆起腹部的异常位移和剧烈扭曲。','未知；按妲咪判断可能想避免被提前识别并完成出生。','在接近扫描室时强烈抵抗，其他情境未展示。','从腹中施力牵动母体，足以令外人难以拉住；活动载体与范围局限明显。',[(55,59,'剧烈胎动'),(69,85,'扫描前抵抗与结局')],[('载体接近可能暴露它的检查','与原文扫描威胁相近','加强局部运动抵抗，不能自动破坏远处设备。'),('母体试图逆其方向移动','彼此意愿冲突','通过身体扭曲争夺移动方向。'),('已脱离原载体','缺乏独立活动证据','不凭空产生新身体或选择下个宿主。')],roles=['反派','阶段性对立者'],ghost=True,confidence='medium',scores={'physical':3,'energy':1,'scope':0,'sustain':1,'range':0,'combat':1},tier='纸',deployment='若场景必须让其出现，仅限原有母体内状态的明确回溯，不默认为已出生实体。',baseline={'destruction':'能以腹中力量牵动母体，未展示外部物体破坏。','durability':'独立本体不可见，承伤方式未知。','speed':'一次带动母体快速奔出；不得当作独立超高速。','energy':'异常控制母体运动，是否灵体未明。'},uncertainties=['身份、动机、是否畏惧扫描均有推断成分。','没有出生后的形态及战力证据。'])])
B('鸡蛋',[
C('egg_boy','观察鸡蛋的少年','他十三岁，刚由小学升入中学，原本是一个成绩中等、生活普通的城市孩子。十二岁时曾要求父母尊重房门与隐私，父母把这看成成长的表现。为了观察胚胎发育，他从鸡场购买可孵化的鸡蛋，调节小电炉温度，每天打开一个，记录变化；随着看到半成形的小鸡，他开始问未经受精的蛋是否算生命、弄破发育中的蛋是否像屠杀，显示科学功课也激发了伦理不安。第二十天房里突然传来惊叫，他左手流血，却不愿说明；空蛋壳里不见应有的雏鸡，他又格外珍惜剩下的一只蛋。那蛋孵成母鸡后，他与之亲近到家人感到被冷落，停止吃鸡蛋，父亲开杀鸡玩笑时会露出强烈恨意。一年后露营，同学不知那是宠物而宰食，他杀死两个同学后逃入养鸡场，从此失踪。结尾暗示可能有变形，却没有直接确认。终局的他已越过为宠物辩护的界限成为致命加害者，能力仍只能计人身和现场器具；疑似与鸡认同的变化，不等于能召唤禽群、复活宠物或自由变鸡。','杀死两名同学后逃往养鸡场失踪，是否化鸡未证实。','普通少年，事故后神情古怪，字迹后来扭曲潦草。','保护母鸡及与它的特殊联系；对伤害其所爱者产生极端愤怒。','起初沉默保护隐私，宠物受害后骤然失控。','做观察记录、照料母鸡；能用现场铁叉伤人，无超常战斗训练证据。',[(11,35,'实验、隐私与生命问题'),(45,61,'异常转变、宠物关系和杀人失踪')],[('脆弱生命依赖自己','已形成感情联系','投入持续照料，拒绝把它仅当食物。'),('别人把他的忧虑当玩笑','触及宠物安全','会露出明显敌意，提供可观察预警。'),('亲密对象被杀害','愤怒压过判断','存在冲动伤人的风险，应允许外界制止，不能保证必杀。')],roles=['主角','反派'],scores={'physical':1,'energy':0,'scope':0,'sustain':1,'range':1,'combat':2},tier='纸',uncertainties=['手伤当晚具体发生何事未揭。','逃入农场后的形态变化只有暗示。']),
C('egg_father','观察鸡蛋少年的父亲','他有稳定职业、自置住宅、汽车和一个成绩普通的儿子，与妻子的感情也仍温暖。这样的生活使他习惯把异常先放进正常成长的框架里解释。看见儿子切开鸡蛋，他先吃惊好奇，听妻子解释是胚胎观察功课后便放下疑虑，还为孩子提问题而感到家庭的满足。孩子曾要求进房敲门，他也欣然尊重；后来房内惊叫、手上流血，父母急忙拍门，见工具和蛋壳便推定只是割伤，没有注意蛋壳里缺少应有的小鸡。儿子逐渐把孵出的母鸡视作最重要的伙伴，他一度以玩笑提议宰鸡，却被孩子强烈的恨意吓到。尽管如此，其他古怪举动仍被归为青春期，直到露营老师来电，告知宠物被同学杀食，儿子已杀人逃走，他才立即明白灾难的严重。终局的他面对失踪、死亡与自己漏看信号的事实，没有得到怪事的确切解释。演绎应保留爱子与日常善意，也呈现过度安心的盲点；他可以学习把孩子的表达当真，不能凭事后明白就读透所有少年的内心。','得知儿子杀人并失踪，此后下落未明。','普通中产父亲，具体外观未详；家庭相处温和。','维持温暖家庭，保护并理解正在长大的孩子。','先以常识安慰自己，真正危急时与妻子共同求证。','家长照料和生活判断；无侦查或超常鉴定能力。',[(9,35,'家庭状态和功课解释'),(39,61,'漏看线索、玩笑及灾难通知')],[('孩子提出独立要求','看似正常成长','愿意尊重隐私，保持可交谈入口。'),('异样被日常解释覆盖','仍有不吻合的物证','需要重新查看，不能只用青春期敷衍。'),('孩子的重要关系受威胁','已经出现强烈情绪','认真处理安全问题，不再仅用玩笑试探。')])],excluded=[{'name':'母亲','reason':'一次性照料者，行动与父亲共构家庭背景，未独立展开主线。'},{'name':'两名被杀同学','reason':'不知宠物身份而宰鸡，未显示独立恶意；不把死者自动列反派。'},{'name':'宠物母鸡','reason':'特殊关系明显但未表现可辨的独立人格或对抗行动。'}])
(P/'ghost_f.draft.json').write_text(json.dumps(books,ensure_ascii=False,indent=2),encoding='utf-8')
